import { useState } from 'react';
import { useScrollReset } from '@/components/ScrollToTop';
import { ChevronLeft, ChevronRight, CheckCircle2, XCircle, RotateCcw, Trophy, BookOpen, ChevronDown, ChevronUp } from 'lucide-react';
import { useEntitlement } from '@/hooks/useEntitlement';
import PaywallModal from '@/components/PaywallModal';
import QuizFreePreviewGate from './QuizFreePreviewGate';

const FREE_PREVIEW_LIMIT = 5;

const QUESTIONS = [
  { id: 1, domain: 'I — Pharmacology', q: 'A 68-year-old with ESRD receives rocuronium 0.6 mg/kg. After 4 hours, which reversal is MOST appropriate?', options: ['Neostigmine 0.05 mg/kg with glycopyrrolate — standard reversal at 4 hours', 'Sugammadex 2 mg/kg — at T2 recovery, regardless of renal status', 'Sugammadex 4 mg/kg — renal failure prolongs rocuronium but sugammadex is still preferred', 'Neostigmine alone — glycopyrrolate should be avoided in renal failure'], answer: 2, rationale: 'Sugammadex 4 mg/kg is preferred in ESRD. Renal failure prolongs rocuronium; sugammadex provides complete, quantifiable reversal superior to neostigmine. Use 4 mg/kg (not 2 mg/kg) for more complete reversal at shallow block in ESRD, and monitor for re-curarization.' },
  { id: 2, domain: 'I — Pharmacology', q: 'Bupivacaine 0.5% epidural causes sudden cardiovascular collapse with wide-complex dysrhythmia. The MOST critical immediate intervention?', options: ['Defibrillation at 200J biphasic', 'Intralipid 20% 1.5 mL/kg IV bolus', 'Sodium bicarbonate 1-2 mEq/kg IV', 'Amiodarone 300 mg IV push'], answer: 1, rationale: 'LAST from bupivacaine — the most cardiotoxic local anesthetic. Intralipid 20% 1.5 mL/kg bolus then 0.25 mL/kg/min infusion creates a "lipid sink" sequestering bupivacaine. Amiodarone is NOT recommended in LAST — it inhibits Na+ channels and may worsen toxicity.' },
  { id: 3, domain: 'I — A&P', q: 'During one-lung ventilation (left lateral decubitus), a patient develops hypoxemia. Which mechanism BEST explains the initial compensatory response?', options: ['Increased cardiac output to the dependent lung', 'Hypoxic pulmonary vasoconstriction (HPV) in the non-dependent lung', 'Increased tidal volume to the dependent lung', 'Reflex bronchodilation in the non-dependent lung'], answer: 1, rationale: 'HPV is the primary compensatory mechanism. When the non-dependent lung is deflated (alveolar hypoxia), HPV causes vasoconstriction, diverting blood to the ventilated lung. Volatile agents blunt HPV and worsen hypoxemia.' },
  { id: 4, domain: 'I — Pharmacology', q: 'Sevoflurane 2% with desiccated CO2 absorbent (soda lime). Which MOST dangerous compound is produced?', options: ['Carbon dioxide', 'Compound A', 'Carbon monoxide', 'Hydrogen fluoride'], answer: 2, rationale: 'Desiccated soda lime (especially with NaOH/KOH) reacts with volatiles to produce carbon monoxide — most immediately life-threatening. Desflurane and isoflurane produce the most CO with desiccated soda lime; sevoflurane produces compound A at low (non-desiccated) flows.' },
  { id: 5, domain: 'I — Physiology', q: 'A patient with PFO undergoes posterior fossa craniotomy (sitting). ETCO2 drops to 22 mmHg and mill-wheel murmur is heard. The MOST dangerous complication specific to the PFO?', options: ['Increased intracranial pressure', 'Paradoxical air embolism causing stroke or coronary air embolism', 'Tension pneumothorax', 'Systemic air embolism from arterial line'], answer: 1, rationale: 'VAE + PFO = paradoxical embolism risk. Air crossing from right atrium to left atrium (via PFO) can cause arterial air embolism — stroke, coronary air embolism, or other end-organ ischemia. This occurs when right atrial pressure exceeds left atrial pressure.' },
  { id: 6, domain: 'I — Pharmacology', q: 'Which correctly describes succinylcholine-induced hyperkalemia and the HIGHEST risk patients?', options: ['Upregulation of extrajunctional ACh receptors → massive K+ efflux; highest risk in burns >72h post-injury', 'Direct inhibition of Na/K ATPase; highest risk in hypokalemia', 'Competitive blockade of nicotinic receptors; highest risk in renal failure', 'Phase II block causing prolonged channel opening; highest risk in liver failure'], answer: 0, rationale: 'Upregulation of extrajunctional (immature) nicotinic receptors after burn >72h, denervation, crush injury, or prolonged immobilization leads to massive K+ efflux. K+ can reach 10-14 mEq/L. Critical: succinylcholine is safe in acute burn (<72h) but contraindicated after.' },
  { id: 7, domain: 'I — Pathophysiology', q: 'A HOCM patient develops sudden severe hypotension after propofol induction. The MOST appropriate vasopressor?', options: ['Dopamine 5 mcg/kg/min', 'Epinephrine 10 mcg IV', 'Phenylephrine 100 mcg IV bolus', 'Dobutamine 5 mcg/kg/min'], answer: 2, rationale: 'Phenylephrine is ideal in HOCM. It is a pure alpha-1 agonist increasing SVR without increasing HR or contractility. Reflex bradycardia is actually beneficial. Epinephrine and dobutamine increase contractility and HR — worsening LVOT obstruction. Dopamine also has beta effects, worsening obstruction.' },
  { id: 8, domain: 'I — Pharmacology', q: 'Planning desflurane. The vaporizer temperature display is not illuminated and gas cannot be dialed. The MOST likely reason?', options: ['The vaporizer is out of desflurane', 'The vaporizer heating element has not reached operating temperature (~39°C)', 'The oxygen pipeline pressure is below 45 psig', 'The vaporizer is tilted and cannot be used for 30 minutes'], answer: 1, rationale: 'Desflurane boiling point is 22.8°C — requires a heated, pressurized Tec 6 vaporizer at ~39°C. The system must complete warm-up before allowing gas delivery. This is a safety feature preventing unpredictable vaporization at room temperature.' },
  { id: 9, domain: 'I — Pharmacology', q: 'Remifentanil infusion at 0.2 mcg/kg/min for 4-hour spine surgery. The PRIMARY concern during emergence?', options: ['Prolonged sedation due to remifentanil accumulation', 'Acute opioid-induced hyperalgesia and severe pain on awakening', 'Respiratory depression lasting 6-8 hours post-operatively', 'Re-narcotization requiring naloxone reversal'], answer: 1, rationale: 'Remifentanil does NOT accumulate (organ-independent ester hydrolysis, context-sensitive half-time 3-5 min). However, prolonged infusion causes opioid-induced hyperalgesia (OIH) via NMDA receptor activation. Plan: administer long-acting opioid + ketamine 15-30 min before emergence.' },
  { id: 10, domain: 'I — Pathophysiology', q: '28-week pregnant patient develops tachycardia, bronchospasm, urticaria, and hypotension during induction. CORRECT treatment sequence?', options: ['Epinephrine 0.3 mg IM lateral thigh, then diphenhydramine 50 mg IV', 'Epinephrine 10-100 mcg IV bolus immediately, then airway management and diphenhydramine', 'Hydrocortisone 200 mg IV, diphenhydramine, then epinephrine if no response', 'Albuterol MDI for bronchospasm, then epinephrine IM'], answer: 1, rationale: 'Intraoperative anaphylaxis with IV access → immediate IV epinephrine (10-100 mcg, not 0.3 mg IM). IV route allows faster onset and titration. Steroids and antihistamines are adjuncts, not first-line. Left uterine displacement. Maternal survival takes priority.' },
  { id: 11, domain: 'I — Physics', q: 'E-cylinder reads 1000 psig. Patient requires 3 L/min O2. Approximately how long will it last?', options: ['~100 minutes', '~50 minutes', '~67 minutes', '~150 minutes'], answer: 0, rationale: 'E-cylinder factor = 0.3 L/psig. 1000 × 0.3 = 300 L remaining. At 3 L/min: 300/3 = 100 minutes. Always maintain safety margin — replace if duration <30 min beyond estimated procedure length.' },
  { id: 12, domain: 'I — Pharmacology', q: 'The GREATEST concern using ketamine for sedation in a patient taking an MAOI antidepressant?', options: ['Ketamine + MAOI → malignant hyperthermia', 'Ketamine + MAOI → serotonin syndrome and severe hypertensive crisis', 'Ketamine + MAOI → prolonged neuromuscular blockade', 'Ketamine + MAOI → rapid respiratory depression'], answer: 1, rationale: 'Ketamine inhibits catecholamine reuptake; MAOIs prevent catecholamine breakdown → severe hypertensive crisis and possible serotonin syndrome. Elective surgery: defer until MAOI discontinued 2 weeks. If emergent: avoid all indirect sympathomimetics, careful monitoring.' },
  { id: 13, domain: 'I — Pathophysiology', q: 'A patient with cirrhosis receives vecuronium. Which statement BEST explains the expected change?', options: ['Faster elimination due to compensatory renal clearance', 'Prolonged NMB due to reduced hepatic metabolism and biliary excretion', 'Unchanged duration — vecuronium uses Hofmann elimination', 'Reduced potency due to increased Vd from ascites'], answer: 1, rationale: 'Vecuronium is primarily hepatically eliminated (deacetylation) and biliary excreted. In cirrhosis both are impaired → significantly prolonged duration. Active metabolite 3-desacetylvecuronium also accumulates. Use cisatracurium (Hofmann elimination) in liver failure.' },
  { id: 14, domain: 'I — Pharmacology', q: '80 kg patient with no organ dysfunction requires succinylcholine for RSI. The CORRECT dose?', options: ['80 mg (1 mg/kg)', '120 mg (1.5 mg/kg)', '160 mg (2 mg/kg)', '40 mg (0.5 mg/kg)'], answer: 1, rationale: 'RSI succinylcholine dose: 1.5-2 mg/kg. For 80 kg: 1.5 × 80 = 120 mg. This provides fastest, most complete blockade. 1 mg/kg may be insufficient for RSI conditions. In obese patients, use TBW (increased pseudocholinesterase).' },
  { id: 15, domain: 'I — Pathophysiology', q: 'COPD patient (baseline PaCO2 55) given 4 L/min O2 postop. SpO2 96% but increasingly somnolent. MOST likely mechanism?', options: ['Propofol residual effect causing sedation', 'Nitrous oxide diffusion hypoxia', 'Hyperoxia-induced suppression of the hypoxic ventilatory drive, causing CO2 retention', 'Neuraxial opioid-induced respiratory depression'], answer: 2, rationale: 'In chronic hypercapnia, the CO2 drive is blunted; ventilation relies on hypoxic drive. When supplemental O2 raises SpO2 too high, this drive is eliminated → ventilatory rate decreases → CO2 accumulates. Target SpO2 88-92% in COPD with known CO2 retention.' },
  { id: 16, domain: 'I — Pharmacology', q: 'Which pharmacokinetic property BEST explains propofol\'s faster emergence vs. barbiturates after 3-hour infusion?', options: ['Lower volume of distribution', 'Higher protein binding', 'Organ-independent elimination via Hofmann mechanism', 'Short context-sensitive half-time due to redistribution and rapid hepatic clearance'], answer: 3, rationale: 'Propofol has extremely high hepatic clearance (2 L/min, exceeding hepatic blood flow → extrahepatic metabolism) plus redistribution. Context-sensitive half-time stays short regardless of infusion duration. Thiopental saturates peripheral compartments → "hangover" after long infusions.' },
  { id: 17, domain: 'I — Pathophysiology', q: 'MH-susceptible patient requires emergency surgery. The MOST appropriate anesthetic plan?', options: ['TIVA with propofol + remifentanil; MH-prepared machine', 'Sevoflurane with succinylcholine; dantrolene on standby', 'Spinal with bupivacaine; volatile backup if spinal fails', 'Sevoflurane only; avoid succinylcholine as the more dangerous trigger'], answer: 0, rationale: 'AVOID ALL volatile agents AND succinylcholine — both are MH triggers. TIVA with propofol + remifentanil is the standard. Machine must be prepared: flush with high-flow O2 for 20-60 min, remove vaporizers, change CO2 absorbent and circuits. Dantrolene always immediately available.' },
  { id: 18, domain: 'I — Pharmacology', q: 'Metoclopramide 10 mg IV preoperatively. Which patient raises MOST concern for serious adverse reaction?', options: ['History of peptic ulcer disease', 'History of Parkinson\'s disease', 'History of GERD', 'History of prior PONV'], answer: 1, rationale: 'Metoclopramide is a D2 receptor antagonist. In Parkinson\'s disease, dopaminergic pathways are already compromised → metoclopramide can precipitate severe parkinsonian crisis, rigidity, and extrapyramidal symptoms. GERD and peptic ulcer disease are actually indications for metoclopramide.' },
  { id: 19, domain: 'I — Pharmacology', q: 'Which CORRECTLY describes volatile anesthetic interaction with non-depolarizing NMBAs?', options: ['Volatile agents competitively antagonize NDNMBs at nicotinic receptor', 'Volatile agents potentiate NDNMBs by enhancing post-junctional sensitivity and reducing muscle spindle activity', 'Volatile agents prolong NDNMB action by inhibiting plasma cholinesterase', 'Volatile agents have no significant effect on NDNMB requirement'], answer: 1, rationale: 'Volatile agents (especially isoflurane and desflurane) potentiate NDNMBs by ~20-40% via enhanced post-junctional NMJ sensitivity, depression of muscle spindle activity, and possible pre-junctional effects. Less NDNMB needed; residual block at emergence may be more pronounced.' },
  { id: 20, domain: 'I — Pharmacology', q: 'Patient on buprenorphine 16 mg/day requires emergent laparotomy. MOST appropriate perioperative pain strategy?', options: ['Discontinue buprenorphine immediately and switch to full agonist opioids', 'Continue buprenorphine; rely on regional anesthesia and non-opioid multimodal analgesia; supplement with high-dose full agonist opioids if needed', 'Administer naloxone to clear buprenorphine, then use standard opioid dosing', 'Use meperidine exclusively since it is not blocked by buprenorphine'], answer: 1, rationale: 'Current ASRA/AANA guidance: CONTINUE buprenorphine perioperatively. Abrupt discontinuation risks relapse and withdrawal. Maximize regional anesthesia + multimodal analgesia (ketamine, NSAIDs, acetaminophen). High-dose full agonist opioids can partially displace buprenorphine if needed. Never use naloxone to clear buprenorphine.' },
  { id: 21, domain: 'II — Anesthetic Machine', q: 'Isoflurane vaporizer filled with sevoflurane by mistake using improperly stored device. Which safety system was bypassed?', options: ['Pin Index Safety System (PISS)', 'Diameter Index Safety System (DISS)', 'Agent-specific keyed filling device (Selectatec) system', 'Proportioning system'], answer: 2, rationale: 'Agent-specific keyed filling devices (Selectatec, Quik-Fil) are designed so only the matching agent adapter fits the vaporizer. PISS prevents wrong gas cylinders; DISS is for high-pressure pipeline connections; proportioning system maintains O2/N2O ratios.' },
  { id: 22, domain: 'II — Monitoring', q: 'Arterial line shows systolic 40 mmHg higher than NIBP; diastolic similar on both. What does this suggest?', options: ['Overdamping of the arterial line', 'Underdamping (resonance artifact) causing systolic overshoot', 'Arterial vasospasm at the radial artery', 'Aortic regurgitation'], answer: 1, rationale: 'Underdamped (resonant) waveform: falsely elevated systolic, falsely low diastolic, mean pressure relatively accurate. Confirm with fast-flush test — underdamped shows oscillations before returning to baseline. Overdamping produces the opposite: falsely LOW systolic, HIGH diastolic.' },
  { id: 23, domain: 'II — Airway Equipment', q: 'Cormack-Lehane grade 3 view with Macintosh 3. Which device MOST improves likelihood of successful intubation?', options: ['Switch to Miller 2 blade', 'Apply BURP while using a bougie through the existing view', 'Attempt blind nasal intubation', 'Immediately perform a cricothyrotomy'], answer: 1, rationale: 'Bougie + BURP is the most efficient next step. The bougie tip can pass into the trachea even without seeing the glottis — tactile confirmation from tracheal rings. Cricothyrotomy is for CICO (cannot intubate, cannot oxygenate) — not indicated when oxygenation is maintained.' },
  { id: 24, domain: 'II — Monitoring', q: 'BIS reads 35 during maintenance with sevoflurane 1.5 MAC. The BEST response?', options: ['BIS 35 is optimal for surgical anesthesia; no change needed', 'BIS 35 is dangerously low — reduce to 0.5 MAC immediately', 'BIS 35 is below target 40-60; consider reducing volatile to bring BIS to 40-60', 'BIS is unreliable with volatile anesthetics'], answer: 2, rationale: 'Target BIS for GA: 40-60. BIS 35 suggests deeper-than-necessary anesthesia. Titrate down while confirming clinically (hemodynamics, movement). BIS is validated for volatile and IV agents — it is a useful depth guide when properly applied.' },
  { id: 25, domain: 'II — Anesthetic Machine', q: 'Which is MOST reliable indicator of correct ETT tracheal placement immediately after intubation?', options: ['Bilateral breath sounds on auscultation', 'Visible chest rise during ventilation', 'Consistent ETCO2 waveform on capnography over multiple breaths', 'Tube seen passing through the vocal cords under direct vision'], answer: 2, rationale: 'Sustained square-wave ETCO2 waveform over 3-5+ consecutive breaths is the gold standard. Esophageal intubation can produce 1-2 CO2 waves from gastric CO2 then disappears. Breath sounds and chest rise can mislead in obese patients. Capnography is the ASA standard for ETT confirmation.' },
  { id: 26, domain: 'II — Equipment', q: 'Circle system at 2 L/min FGF; exhaled CO2 progressively rises over 45 minutes; peak flow alarm activates. MOST likely cause?', options: ['Endobronchial intubation', 'CO2 absorbent exhaustion', 'Bronchospasm', 'Ventilator disconnection'], answer: 1, rationale: 'Exhausted CO2 absorbent no longer absorbs CO2; rebreathed CO2 accumulates → rising inspired CO2 and progressive hypercapnia. Manifests as rising baseline capnography waveform. Replace absorbent immediately. Color change from white to purple confirms exhaustion (but do not trust color reversal on standing).' },
  { id: 27, domain: 'II — Monitoring', q: 'Swan-Ganz PCWP of 22 mmHg in a patient with flash pulmonary edema. This MOST likely represents:', options: ['Normal left heart filling pressure', 'Elevated LVEDP suggesting left ventricular failure or volume overload', 'Elevated right ventricular preload only', 'Pulmonary hypertension from hypoxic vasoconstriction'], answer: 1, rationale: 'PCWP approximates LVEDP (normal 6-12 mmHg). PCWP 22 mmHg indicates elevated LVEDP consistent with LV failure, volume overload, or diastolic dysfunction — explaining flash pulmonary edema. In mitral stenosis, PCWP overestimates LVEDP.' },
  { id: 28, domain: 'II — Airway Equipment', q: '4-year-old (18 kg) requires intubation. Age-based uncuffed ETT size and cuff pressure limit if cuffed tube used?', options: ['5.0 uncuffed; cuff pressure <25 cmH2O', '5.0 uncuffed; cuff pressure <30 cmH2O', '4.5 uncuffed; cuff pressure <20 cmH2O', '5.5 uncuffed; cuff pressure <25 cmH2O'], answer: 1, rationale: 'ETT size formula: (Age/4) + 4 = (4/4) + 4 = 5.0 mm ID. Cuffed ETT cuff pressure: <20-30 cmH2O to prevent tracheal mucosal ischemia (most sources cite <20 cmH2O as the protective limit). ETT depth at lip: weight + 10 = 28 cm, or age/2 + 12 = 14 cm.' },
  { id: 29, domain: 'II — Monitoring', q: 'Sitting posterior fossa craniotomy: TEE shows bubbles in right atrium, ETCO2 drops from 38 to 18 mmHg. Which intervention MOST reduces ongoing air entrainment?', options: ['Apply PEEP', 'Flood the surgical field with saline and notify the surgeon to occlude the wound', 'Administer epinephrine 100 mcg IV', 'Perform carotid sinus massage'], answer: 1, rationale: 'Flooding the field with saline creates a water seal preventing further air entry. Notify surgeon for digital pressure/bone wax on wound edges. Simultaneously: Durant maneuver, 100% O2, D/C N2O, aspirate through CVC. PEEP increases CVP but not the first priority.' },
  { id: 30, domain: 'II — Equipment', q: 'Why does a 25-gauge Whitacre pencil-point needle BEST reduce PDPH?', options: ['Pencil-point tip cuts fewer nerve fibers', 'Side-opening design and pencil-point tip separate, rather than cut, dural fibers, allowing them to recoil and self-seal', 'Smaller gauge alone prevents CSF leakage', 'Pencil point creates a larger opening that allows CSF to drain slowly'], answer: 1, rationale: 'Pencil-point needles (Whitacre, Sprotte) have a non-cutting tip that separates dural fibers rather than cutting them, allowing fibers to spring back and self-seal after withdrawal. This dramatically reduces CSF leakage. Using 25-27g Whitacre reduces PDPH from ~36% (16g Tuohy) to <1%.' },
  { id: 31, domain: 'II — Equipment', q: 'Mapleson D (Bain) circuit; controlled ventilation; MV = 7 L/min. FGF needed to prevent rebreathing?', options: ['7 L/min (equal to MV)', '3.5 L/min (half of MV)', '14 L/min (2× MV)', '21 L/min (3× MV)'], answer: 2, rationale: 'Mapleson D (Bain) for controlled ventilation: FGF = 2× MV. At 7 L/min MV: 2 × 7 = 14 L/min. For spontaneous ventilation on Mapleson D: FGF = 3× MV. Mapleson A (Magill) is most efficient for spontaneous ventilation (FGF = MV).' },
  { id: 32, domain: 'II — Monitoring', q: 'Laparoscopic cholecystectomy: peak airway pressure increases from 22 to 45 cmH2O; plateau pressure remains at 20 cmH2O. MOST likely cause?', options: ['Development of pneumothorax', 'ETT obstruction (kink, secretions, or patient biting)', 'Development of pulmonary edema', 'Ventilator malfunction'], answer: 1, rationale: 'HIGH PEAK + NORMAL PLATEAU = increased airway RESISTANCE (not compliance problem). Difference between peak and plateau reflects resistance of airway/ETT. Causes: ETT kink, biting, mucus plugging, bronchospasm. Pneumothorax and pulmonary edema increase BOTH peak and plateau (reduced compliance).' },
  { id: 33, domain: 'II — Equipment', q: 'Standard pulse oximeter on CO poisoning patient reads SpO2 97%. MOST important interpretation?', options: ['SpO2 97% confirms adequate oxygenation; CO poisoning unlikely', 'SpO2 97% is falsely normal — standard pulse oximetry cannot distinguish oxyhemoglobin from carboxyhemoglobin', 'SpO2 97% confirms normal CO-Hgb as CO poisoning would read <85%', 'SpO2 97% indicates device is malfunctioning'], answer: 1, rationale: 'Standard pulse oximeters use 2 wavelengths (660 and 940 nm) and CANNOT distinguish oxyhemoglobin from carboxyhemoglobin. COHb absorbs light like HbO2 at 660 nm → falsely high SpO2. Patient with 40% COHb could read SpO2 97%. Diagnosis requires co-oximetry (ABG). Treat with 100% FiO2 regardless.' },
  { id: 34, domain: 'II — Equipment', q: 'E-cylinder reads 500 psig. Transport will require 3 minutes at 4 L/min. Is there sufficient oxygen?', options: ['No — 500 psig provides only 100 liters, lasting 25 minutes at 4 L/min', 'Yes — 500 psig provides 150 liters, lasting 37.5 minutes at 4 L/min', 'No — 500 psig is below minimum safe threshold of 1000 psig', 'Yes — 500 psig provides 150 liters, more than enough for 3 minutes'], answer: 3, rationale: '500 psig × 0.3 L/psig = 150 liters. At 4 L/min: 150/4 = 37.5 minutes. 3-minute transport needs only 12 liters. 150 liters is more than sufficient. Standard practice: maintain ≥30 min reserve above estimated use.' },
  { id: 35, domain: 'II — Monitoring', q: 'Craniotomy with SSEPs and MEPs: neurophysiologist reports 50% MEP amplitude drop. Which anesthetic change is MOST likely responsible?', options: ['Increasing propofol from 75 to 100 mcg/kg/min', 'Increasing sevoflurane from 0.5 to 1.0 MAC', 'Adding fentanyl 100 mcg IV bolus', 'Increasing dexmedetomidine from 0.3 to 0.5 mcg/kg/hr'], answer: 1, rationale: 'MEPs are exquisitely sensitive to volatile agents in a dose-dependent manner. Doubling sevoflurane from 0.5 to 1.0 MAC can easily cause 50% MEP amplitude drop. Standard: TIVA with propofol + opioid for neuromonitoring cases; volatile <0.5 MAC if used at all. Opioids and dexmedetomidine have minimal MEP impact.' },
  { id: 36, domain: 'II — Equipment', q: 'RSI needed in ED; only rocuronium 1.2 mg/kg available; sugammadex unavailable. MOST accurate statement?', options: ['Rocuronium 1.2 mg/kg is acceptable RSI dose but sugammadex should be present before proceeding', 'Rocuronium 0.6 mg/kg should be used instead since 1.2 mg/kg cannot be reversed without sugammadex', 'Succinylcholine is absolutely required for RSI; rocuronium cannot be used without sugammadex', 'Rocuronium 1.2 mg/kg provides RSI conditions equivalent to succinylcholine; however, must be committed to the airway — consider CICO plan'], answer: 3, rationale: 'Rocuronium 1.2 mg/kg provides RSI conditions equivalent to succinylcholine 1.5 mg/kg. Without sugammadex, block lasts 60-90 min — no reversal option if CICO occurs. Provider must have thorough CICO plan (SGA, cricothyrotomy) before proceeding.' },
  { id: 37, domain: 'II — Equipment', q: 'Which mechanism explains why a Bain circuit is described as "coaxial"?', options: ['It uses two separate breathing bags for inhalation and exhalation', 'The fresh gas supply tube runs inside the outer corrugated exhalation limb', 'Fresh gas flows in the outer tube while exhaled gas exits through the inner tube', 'It has two CO2 absorber canisters arranged coaxially'], answer: 1, rationale: '"Coaxial" means one tube runs inside another. In the Bain circuit, the fresh gas supply tube runs INSIDE the outer corrugated (exhalation) tube. Key safety concern: if the inner tube disconnects internally, patient will rebreathe exhaled gas. Check by occluding the inner tube and watching for flush to distend the bag.' },
  { id: 38, domain: 'II — Monitoring', q: 'Right total hip replacement (lateral decubitus): SpO2 drops to 88%, breath sounds decreased on the right. MOST likely explanation?', options: ['Dependent lung (left) atelectasis', 'Pneumothorax of the right (non-dependent) lung', 'Endobronchial intubation into the left mainstem, ventilating only the dependent lung', 'Right pleural effusion from IV overload'], answer: 2, rationale: 'In right lateral decubitus, left lung is dependent. If ETT migrates into LEFT mainstem bronchus (longer, straighter when left-side down), only left lung is ventilated → reduced breath sounds on the right (non-dependent side), right atelectasis, and hypoxemia. Withdraw ETT to above carina and confirm with FOB.' },
  { id: 39, domain: 'II — Equipment', q: 'Low-pressure leak test identifies a leak during machine checkout. MOST common cause?', options: ['Faulty oxygen cylinder yoke', 'Cracked or improperly seated vaporizer O-ring or filler cap', 'Malfunctioning pressure regulator', 'Broken pipeline inlet check valve'], answer: 1, rationale: 'The low-pressure system (flowmeters to common gas outlet, including vaporizer) is the most common leak site. Most frequent cause: faulty, missing, or improperly seated vaporizer O-ring or incompletely tightened filler cap. These rubber seals degrade over time.' },
  { id: 40, domain: 'II — Monitoring', q: 'Intraoperative TEE after induction. Which finding is MOST concerning for acute myocardial ischemia?', options: ['Trace mitral regurgitation', 'LV wall motion abnormality (regional hypokinesis) in the distribution of the LAD', 'Hyperdynamic LV with decreased end-systolic volume', 'Mild aortic valve calcification with preserved leaflet excursion'], answer: 1, rationale: 'Regional wall motion abnormalities (hypokinesis, akinesis, dyskinesis) in a coronary distribution are the earliest intraoperative sign of ischemia — preceding ECG changes by minutes. Hypokinesis in the LAD territory (anterior wall, septum, apex) = anterior ischemia. Immediately notify surgeon and optimize hemodynamics.' },
  { id: 41, domain: 'III — Airway', q: 'Obese male (BMI 44) for laparoscopic bariatric surgery: peak pressure 34, plateau 28 cmH2O. Which intervention MOST improves compliance and oxygenation?', options: ['Increase respiratory rate to 18 breaths/min', 'Apply PEEP 8-10 cmH2O and reverse Trendelenburg 15 degrees', 'Reduce tidal volume to 4 mL/kg IBW', 'Switch to volume-controlled ventilation'], answer: 1, rationale: 'PEEP 8-10 cmH2O recruits atelectatic lung units; reverse Trendelenburg reduces diaphragmatic loading from abdominal contents. This combination is standard in bariatric laparoscopic surgery. TV should be based on IBW (6-8 mL/kg IBW), not TBW.' },
  { id: 42, domain: 'III — Regional', q: 'Spinal for cesarean delivery. 5 min post-injection: BP drops from 118/72 to 72/44, late FHR decelerations. FIRST-LINE treatment?', options: ['Ephedrine 10 mg IV', 'Phenylephrine 100 mcg IV bolus; increase IV fluid rate; left uterine displacement', 'Epinephrine 10 mcg IV', 'Trendelenburg to increase spinal block height'], answer: 1, rationale: 'Phenylephrine is now first-line for spinal hypotension in OB — less fetal acidosis than ephedrine (ephedrine crosses placenta and causes fetal metabolic acidosis). Prophylactic phenylephrine infusion is now recommended in elective cesarean. Trendelenburg increases block height — risk of high/total spinal.' },
  { id: 43, domain: 'III — Fluid Management', q: '70 kg male, 4-hour colectomy, EBL 800 mL. Which BEST guides intraoperative fluid administration?', options: ['Fixed formula: 4 mL/kg/hr maintenance + 3rd space losses', 'Dynamic fluid responsiveness (PPV >13%, SVV) with bolus-based resuscitation', 'CVP targeting 8-12 mmHg throughout', 'Administer 1 L LR per hour regardless of blood pressure'], answer: 1, rationale: 'Goal-directed fluid therapy (GDFT) using dynamic markers (PPV, SVV, stroke volume response) guides bolus-based fluid administration. Reduces unnecessary fluids, postoperative complications, and length of stay. CVP is a poor predictor of fluid responsiveness and should not be the sole guide.' },
  { id: 44, domain: 'III — Airway', q: 'Mallampati IV, 3 cm mouth opening, thick neck, history of difficult intubation. Elective shoulder arthroplasty. MOST appropriate airway strategy?', options: ['Proceed with RSI using video laryngoscopy', 'Perform awake fiberoptic intubation after topicalization and airway blocks', 'Use size 4 LMA and avoid intubation', 'Attempt direct laryngoscopy with surgical colleague available for tracheotomy'], answer: 1, rationale: 'Known difficult airway = primary indication for awake fiberoptic intubation (AFOI). AFOI preserves spontaneous ventilation and airway tone. Video laryngoscopy is excellent for unanticipated difficult airways but NOT first choice for a known anticipated difficult airway — it requires inducing GA first, committing to an apneic patient.' },
  { id: 45, domain: 'III — Pain', q: 'Opioid-tolerant patient (morphine ER 60 mg BID) for open spinal fusion. Which perioperative strategy has STRONGEST evidence?', options: ['High-dose IV opioid infusion (morphine PCA)', 'Multimodal analgesia: ketamine infusion 0.1-0.3 mg/kg/hr, ketorolac, acetaminophen, and regional anesthesia', 'Increasing oral opioid dose to 100 mg q12h preoperatively', 'Gabapentin 300 mg once preoperatively only'], answer: 1, rationale: 'Multimodal analgesia targeting multiple pain pathways is evidence-based for opioid-tolerant patients. Ketamine at subanesthetic doses is particularly valuable — antagonizes NMDA receptors, reduces central sensitization and opioid-induced hyperalgesia, reduces perioperative opioid consumption.' },
  { id: 46, domain: 'III — Preoperative', q: 'Drug-eluting stent placed 5 months ago; on clopidogrel + aspirin. Elective inguinal hernia repair. MOST appropriate approach?', options: ['Proceed; hold both antiplatelet agents 7 days before', 'Delay surgery until at least 6 months post-stent; continue dual antiplatelet therapy', 'Proceed on aspirin alone; hold clopidogrel for 5 days', 'Continue both antiplatelet agents through surgery'], answer: 1, rationale: 'ACC/AHA guidelines: wait ≥6 months after drug-eluting stent (DES) before elective noncardiac surgery. At 5 months, this patient is still in the high-risk window. Stopping DAPT before 6 months → in-stent thrombosis risk (~30% mortality). Delay surgery and maintain DAPT.' },
  { id: 47, domain: 'III — PACU', q: 'Persistent masseter spasm after succinylcholine 1.5 mg/kg + sevoflurane induction. Temp 37.8°C, ETCO2 48. MOST concerning diagnosis and next step?', options: ['Laryngospasm — increase sevoflurane and jaw thrust', 'Possible masseter muscle rigidity (MMR)/early MH — stop volatile, initiate TIVA, monitor, prepare dantrolene', 'Phase II succinylcholine block — administer neostigmine', 'Medication error — verify and give additional succinylcholine dose'], answer: 1, rationale: 'MMR after succinylcholine is a potential early MH warning. Rising ETCO2 and temperature further raise concern. Response: (1) stop ALL volatile agents, (2) switch to TIVA, (3) increase monitoring (temp, ETCO2, ABG, CK), (4) prepare dantrolene. Administering more succinylcholine in suspected MH is absolutely contraindicated.' },
  { id: 48, domain: 'III — Fluids', q: 'CHF patient (EF 30%), 3-hour hysterectomy: TEE shows dilated LV, poor systolic function. BP 78/50, HR 115. MOST appropriate medication combination?', options: ['Phenylephrine infusion + fluid bolus 1 L LR', 'Dobutamine infusion + vasopressor as needed + judicious fluid resuscitation', 'Metoprolol 5 mg IV to slow HR + fluid bolus', 'Nitroprusside infusion to reduce afterload'], answer: 1, rationale: 'Cardiogenic shock: poor contractility, not vasodilation. Management: (1) dobutamine to improve contractility, (2) vasopressor (NE or vasopressin) to maintain perfusion pressure, (3) careful fluids — avoid volume overload in a dilated, failing LV. Phenylephrine increases afterload — poorly tolerated in failing LV. Beta-blockade in acute cardiogenic shock is contraindicated.' },
  { id: 49, domain: 'III — Positioning', q: 'After 3.5-hour lithotomy position: bilateral calf pain, weakness in dorsiflexion, numbness over dorsum of foot. MOST likely injured nerve?', options: ['Femoral nerve', 'Sciatic nerve', 'Common peroneal nerve', 'Obturator nerve'], answer: 2, rationale: 'Common peroneal nerve is the most frequently injured nerve in lithotomy — wraps around the fibular head, compressed against leg holders. Innervates dorsiflexion and sensory to dorsum of foot. Prevention: ensure lateral fibular head is not compressed; pad all bony prominences.' },
  { id: 50, domain: 'III — Ethics', q: 'Competent Jehovah\'s Witness signed blood refusal form. Intraoperative: loses 2500 mL, Hgb 5.8, hemodynamically unstable. MOST appropriate action?', options: ['Administer blood products immediately — implied consent applies to emergencies', 'Honor the documented, competent refusal; maximize non-blood strategies (cell salvage, vasopressors, TXA, crystalloid)', 'Contact hospital ethics committee for emergency authorization', 'Contact next of kin for surrogate consent'], answer: 1, rationale: 'A competent adult\'s informed refusal of blood products is legally and ethically binding, even life-threatening. The pre-op refusal was signed while competent. Must honor this advance directive. Maximize: cell salvage, vasopressors, TXA, erythropoietin, IV iron, crystalloid. Ethics committee and family CANNOT override a competent patient\'s prior informed refusal.' },
  { id: 51, domain: 'III — Airway', q: 'Complete laryngospasm in a spontaneously breathing child WITHOUT IV access. MOST appropriate initial treatment?', options: ['Nasopharyngeal airway insertion', 'Intramuscular succinylcholine 4 mg/kg in the lateral thigh', 'High-flow O2, jaw thrust, CPAP, call for IV access', 'Immediate orotracheal intubation without medications'], answer: 1, rationale: 'Complete laryngospasm without IV access: IM succinylcholine 4 mg/kg (higher than IV due to slower absorption) — given in lateral thigh or deltoid. This is a life-saving intervention. Note: jaw thrust + CPAP + 100% O2 is the first attempt for PARTIAL laryngospasm; complete laryngospasm unresponsive to CPAP requires succinylcholine.' },
  { id: 52, domain: 'III — PACU', q: 'PACU after laparoscopic appendectomy: restless, confused, tachycardic 118, distended abdomen, SpO2 95%. Had morphine 4 mg intraop. FIRST complication to rule out?', options: ['Morphine allergy', 'Urinary retention', 'Intra-abdominal hemorrhage or bowel perforation', 'Opioid-induced sedation'], answer: 2, rationale: 'Restlessness + tachycardia + abdominal distension after intra-abdominal surgery = surgical emergency until proven otherwise (hemorrhage, anastomotic leak, bowel perforation). Opioid sedation causes sedation + respiratory depression, not agitation and tachycardia. Urgent assessment: VS trend, abdominal exam, Hgb, and immediate surgical team communication.' },
  { id: 53, domain: 'III — Airway', q: 'LMA oral surgery case: capnography shows consistent upsloping plateau (shark-fin) with ETCO2 peak 52 mmHg. Patient spontaneously breathing. What does this indicate?', options: ['Esophageal intubation with persistent CO2 from gastric gas', 'Obstructive pattern consistent with bronchospasm or partial airway obstruction', 'Normal waveform for spontaneously breathing patient under anesthesia', 'Pulmonary embolism causing dead space'], answer: 1, rationale: '"Shark-fin" (obstructive) capnography: prolonged upsloping alveolar plateau reflecting uneven alveolar emptying from airway obstruction — bronchospasm, partial ETT obstruction, or kinked airway. Elevated ETCO2 confirms hypoventilation/obstruction. Assess for bronchospasm (wheeze, peak pressure) and treat with bronchodilators.' },
  { id: 54, domain: 'III — Pharmacology', q: 'Which CORRECTLY describes neostigmine-glycopyrrolate mechanism for NMB reversal?', options: ['Neostigmine directly binds nicotinic receptors to displace NDNMB; glycopyrrolate prevents bradycardia', 'Neostigmine inhibits acetylcholinesterase, increasing ACh at NMJ; glycopyrrolate (quaternary amine) blocks muscarinic side effects without crossing BBB', 'Glycopyrrolate inhibits NDNMB breakdown; neostigmine prevents bradycardia', 'Both act on nicotinic receptors simultaneously'], answer: 1, rationale: 'Neostigmine inhibits acetylcholinesterase → increased ACh at NMJ → competitively overcomes NDNMB. ACh also accumulates at muscarinic receptors → bradycardia, increased secretions, bronchospasm. Glycopyrrolate (quaternary amine) blocks muscarinic side effects without crossing the blood-brain barrier (unlike atropine).' },
  { id: 55, domain: 'III — Safety', q: 'CRNA asked to administer anesthesia for ECT. Which statement regarding ECT anesthetic management is MOST accurate?', options: ['Succinylcholine is contraindicated in ECT because of seizure risk', 'Goal is deep GA with high MAC volatile to prevent awareness', 'Short-acting agents (methohexital or propofol) + succinylcholine modify the motor response; etomidate preferred for lower seizure threshold', 'Ketamine is preferred because it prevents the sympathetic surge'], answer: 2, rationale: 'ECT goals: brief unconsciousness/amnesia + motor modification. Methohexital preferred (lower seizure threshold than propofol). Etomidate also preserves lower seizure threshold. Succinylcholine modifies (not prevents) the seizure. Ketamine increases sympathetic tone — worsening the CVS surge already seen with ECT.' },
  { id: 56, domain: 'III — Fluids', q: 'After 4 L of normal saline: pH 7.28, PaCO2 38, HCO3 17, Na 142, Cl 118. MOST likely diagnosis?', options: ['Respiratory acidosis from hypoventilation', 'Metabolic alkalosis from crystalloid administration', 'Hyperchloremic (non-anion gap) metabolic acidosis from excessive normal saline', 'Mixed respiratory and metabolic acidosis'], answer: 2, rationale: 'Normal saline (154 mEq/L Cl) → high chloride load dilutes bicarbonate → hyperchloremic (non-anion gap) metabolic acidosis. Check: AG = 142 - (118 + 17) = 7 — normal (8-12), confirming non-anion gap. PaCO2 38 = normal → no respiratory component. Balanced crystalloids (LR, Plasmalyte) have lower chloride and less risk.' },
  { id: 57, domain: 'III — Pain', q: 'Which correctly identifies the Apfel PONV Risk Score and the threshold for 2-agent prophylaxis?', options: ['Risk factors: female sex, non-smoking, history of PONV/motion sickness, postoperative opioids; score 2 = intermediate risk, 2 agents recommended', 'Risk factors: age >50, male sex, general anesthesia, nitrous oxide use; score 3 = high risk', 'Risk factors: obesity, diabetes, opioid allergy, prone positioning; score 2+ → droperidol', 'Risk factors: female sex, prior C-section, general anesthesia, GERD; score 3 = high risk'], answer: 0, rationale: 'Apfel score: 1 point each for (1) female sex, (2) non-smoker, (3) history of PONV/motion sickness, (4) postoperative opioids expected. Score 2 = ~40% risk (intermediate); score 3 = ~60%; score 4 = ~80%. SAMBA recommends 2+ agents for score ≥2; multimodal prophylaxis + TIVA for score ≥3.' },
  { id: 58, domain: 'III — Safety', q: 'Laser used in airway (microlaryngoscopy). Which precaution is MOST critical to prevent airway fire?', options: ['Increase FiO2 to 100% to prevent hypoxia', 'Use FiO2 as low as clinically tolerable (ideally <30%) and a laser-resistant ETT', 'Soak the ETT in saline before use', 'Flood the trachea with saline via the ETT'], answer: 1, rationale: 'Airway fire triangle: ignition (laser) + fuel (ETT, tissue) + oxidizer (O2, N2O). Critical prevention: (1) minimize FiO2 <30% (always <40% with active laser), (2) laser-resistant ETT (metallic-wrapped), (3) cuff inflated with saline + methylene blue, (4) avoid N2O. FiO2 100% with airway laser is extremely dangerous.' },
  { id: 59, domain: 'III — Neuraxial', q: 'CSE for labor analgesia. 20 min later: cannot feel legs, BP 70/40, cold sensation blocked to T2. What occurred and treatment?', options: ['Normal high spinal from standard CSE dose — no treatment needed', 'Total/high spinal from intrathecal migration of epidural catheter; treat with fluids, vasopressors, prepare for intubation if apneic', 'Epidural hematoma — immediate MRI', 'Epidural abscess — empiric antibiotics and neurosurgery consult'], answer: 1, rationale: '"Total spinal" — epidural catheter migrated intrathecally; full spinal dose delivered into CSF. One of the most serious neuraxial complications. Treatment: 100% O2, vasopressors, IV fluid bolus, left uterine displacement. Prepare for immediate intubation if block reaches C3-C5 (phrenic nerve paralysis → apnea).' },
  { id: 60, domain: 'III — PACU', q: 'PACU: pink frothy secretions from ETT (still intubated) 30 min after reversal of laryngospasm. MOST likely diagnosis and treatment?', options: ['Pneumonia — broad-spectrum antibiotics', 'Negative pressure pulmonary edema (NPPE) — CPAP, diuresis, supportive care', 'Flash pulmonary edema from fluid overload — reduce IV fluid rate', 'Pulmonary embolism — heparin anticoagulation'], answer: 1, rationale: 'NPPE: forceful inspiratory effort against closed glottis (laryngospasm) generates extreme negative intrathoracic pressure (-40 to -140 cmH2O) → increases pulmonary venous return → fluid into alveoli. Typically appears 30-60 min after relieving obstruction. Treatment: O2/CPAP/BiPAP, diuresis. Usually resolves in 12-24 hours.' },
  { id: 61, domain: 'III — Preoperative', q: 'OSA patient (BMI 38) for outpatient laparoscopic cholecystectomy. MOST important discharge consideration?', options: ['Patient must remain in PACU for 6 hours regardless of clinical status', 'If no CPAP at home, prescribe a nasal airway for discharge', 'Ensure standard discharge criteria met, adequate pain control without residual opioid sedation, responsible adult escort; prescribe home CPAP if not using', 'Admit all OSA patients for 23-hour observation'], answer: 2, rationale: 'OSA outpatient discharge: individualized based on procedure complexity, anesthetic used, pain control (prefer non-opioid multimodal), OSA severity, and CPAP availability. Standard discharge criteria must be met. Opioid minimization critical — residual opioid + OSA significantly increases post-discharge hypoxemia risk.' },
  { id: 62, domain: 'III — Pharmacology', q: 'Dexmedetomidine infusion at 0.7 mcg/kg/hr for ICU sedation: HR 38 bpm, BP 82/50. MOST appropriate intervention?', options: ['Increase dexmedetomidine dose — bradycardia indicates inadequate pain control', 'Reduce or discontinue dexmedetomidine; administer atropine if symptomatic; glycopyrrolate if needed', 'Administer adenosine to differentiate from SVT', 'Immediately cardiovert at 50J synchronized'], answer: 1, rationale: 'Dexmedetomidine (alpha-2 agonist) causes sedation + bradycardia + hypotension, especially at higher doses. Symptomatic bradycardia requires reducing/stopping infusion and treating with atropine 0.5 mg IV or glycopyrrolate. Avoid rapid bolus administration — can cause transient hypertension followed by profound bradycardia.' },
  { id: 63, domain: 'III — Safety', q: 'Per AANA standards, which represents MINIMUM monitoring during all general anesthetic procedures?', options: ['Arterial line, CVP, foley catheter', 'ECG, noninvasive BP, pulse oximetry, capnography, temperature', 'ECG, pulse oximetry, capnography only', 'Pulse oximetry and blood pressure only'], answer: 1, rationale: 'AANA/ASA minimum standards for GA: (1) ECG continuous, (2) NIBP at appropriate intervals, (3) pulse oximetry, (4) capnography (ETCO2 for intubated/SGA patients), (5) temperature when clinically significant changes expected. Additional monitoring (A-line, PA catheter, TEE) based on patient/procedure complexity.' },
  { id: 64, domain: 'III — Airway', q: 'Known subglottic stenosis (trachea narrowed to 6 mm) for elective procedure. MOST appropriate airway management?', options: ['Select 6.0 mm ID ETT and proceed with RSI', 'Awake fiberoptic intubation with small-diameter ETT (5.0-5.5 mm), avoiding excessive sedation', 'Use supraglottic airway — subglottic stenosis does not affect LMA placement', 'Cancel and refer to ENT — subglottic stenosis cannot be managed by CRNAs'], answer: 1, rationale: 'Subglottic stenosis = anticipated difficult airway → awake fiberoptic intubation is safest. Preserves airway tone, spontaneous ventilation, allows navigation of the stenosis under direct vision. RSI commits to an apneic patient with known stenosis — extremely dangerous. CRNAs are trained for complex airway management including fiberoptic techniques.' },
  { id: 65, domain: 'III — Regional', q: 'Interscalene block for shoulder arthroscopy. 30 min later: SOB, SpO2 94%, ipsilateral hemidiaphragm elevation on CXR. Which complication occurred?', options: ['Pneumothorax from needle injury to apex of lung', 'Ipsilateral phrenic nerve palsy (100% incidence with interscalene block)', 'Contralateral phrenic nerve injury', 'Cervical epidural spread causing bilateral respiratory depression'], answer: 1, rationale: 'Phrenic nerve palsy (C3-C5) is a 100% incidence side effect of interscalene block — the phrenic nerve runs through the interscalene groove. Ipsilateral hemidiaphragm is paralyzed → ~25% reduction in pulmonary function. Clinically insignificant in healthy patients but relative contraindication in severe COPD or contralateral lung disease. Resolves in 12-18 hours.' },
  { id: 66, domain: 'III — Fluids', q: 'Trauma patient TEG: prolonged R time, narrow MA, short fibrinolysis time. MOST appropriate blood product strategy?', options: ['Platelets and cryoprecipitate only', 'FFP and antifibrinolytic (TXA) — prolonged R = factor deficiency; short fibrinolysis = elevated fibrinolytic activity', 'PRBCs only — the primary problem is anemia', 'Heparin infusion — short R time indicates hypercoagulability'], answer: 1, rationale: 'TEG interpretation: R time = clotting factors (prolonged → factor deficiency → FFP). MA = platelet/fibrinogen strength. Short fibrinolysis time = hyperfibrinolysis → TXA. Prolonged R time means HYPO-coagulable (slow clot formation), not hypercoagulable. Goal-directed TEG/ROTEM therapy reduces unnecessary transfusions.' },
  { id: 67, domain: 'III — Preoperative', q: 'Patient with known or suspected full stomach in emergency. Which BEST describes the anesthetic management?', options: ['Administer ondansetron preoperatively to prevent aspiration', 'RSI: preoxygenate 3-5 min, cricoid pressure, succinylcholine or high-dose rocuronium, intubate immediately without manual ventilation', 'Use LMA since it protects against aspiration better than mask', 'Delay intubation until patient has been NPO for at least 2 hours'], answer: 1, rationale: 'RSI is standard for full stomach. Key elements: (1) Preoxygenate 3-5 min, (2) Cricoid pressure, (3) Succinylcholine 1.5-2 mg/kg or rocuronium 1.2 mg/kg, (4) NO mask ventilation after induction (risk of gastric insufflation), (5) Confirm ETT by capnography immediately. LMAs do NOT protect against aspiration.' },
  { id: 68, domain: 'III — Pharmacology', q: 'Dexamethasone 8 mg IV given at start of 3-hour abdominal hysterectomy. Which BEST describes the evidence-based rationale?', options: ['Prevents adrenal insufficiency in chronic steroid users', 'Reduces PONV, has analgesic properties, reduces airway edema, and has anti-inflammatory effects — given as a single multimodal dose', 'Improves gastric motility and reduces aspiration risk', 'Prevents wound infection by reducing inflammatory response'], answer: 1, rationale: 'Single dose dexamethasone 4-8 mg has multiple perioperative benefits: (1) significant antiemetic effect (similar to ondansetron), (2) analgesic-sparing effect, (3) reduces airway edema, (4) anti-inflammatory. Does not cause clinically significant immunosuppression or adrenal suppression with a single dose.' },
  { id: 69, domain: 'III — Safety', q: 'CRNA working with impaired colleague who smells of alcohol and appears unsteady. MOST appropriate immediate action?', options: ['Complete the current case together, then report after', 'Say nothing — it is not the CRNA\'s professional responsibility to report colleagues', 'Immediately remove the impaired colleague from patient care, notify administration/supervisor, and follow institutional peer assistance protocols', 'Ask the impaired colleague privately to excuse themselves from the case'], answer: 2, rationale: 'AANA Code of Ethics requires immediate action when a colleague poses patient safety risk. Steps: (1) Remove from patient care immediately, (2) Notify supervisory personnel/chief CRNA, (3) Document observations, (4) Assist colleague in accessing peer assistance programs. Failing to act makes the observing provider partially liable.' },
  { id: 70, domain: 'III — Preoperative', q: 'Per ACC/AHA perioperative CV guidelines, which patient requires additional cardiac testing before elective major non-cardiac surgery?', options: ['65-yo with well-controlled HTN, no cardiac symptoms, right hemicolectomy', '58-yo with known CAD, stable angina, DASI ≥4 METs', '70-yo with known severe symptomatic aortic stenosis undergoing vascular surgery', '55-yo with T2DM and normal ECG for laparoscopic cholecystectomy'], answer: 2, rationale: 'ACC/AHA identifies symptomatic severe valvular disease as a major active cardiac condition requiring evaluation before elective noncardiac surgery. Severe symptomatic AS + major vascular surgery = very high-risk. The fixed-CO heart cannot augment output against surgical stress → high perioperative MI and death risk. Consider cardiology consult/TAVR first.' },
  { id: 71, domain: 'III — Airway', q: 'Post-4-hour prone spine surgery: facial edema, swollen lips, tongue protrudes over teeth. MOST appropriate extubation strategy?', options: ['Extubate immediately — airway edema is cosmetic only', 'Keep intubated overnight, extubate in ICU', 'Perform cuff-leak test; if no leak, delay extubation; if leak present, extubate over airway exchange catheter (AEC) with full equipment', 'Perform tracheostomy immediately before extubation'], answer: 2, rationale: 'Significant airway edema after prone surgery with large fluid shifts is a high-risk extubation scenario. Cuff-leak test: deflate cuff — no audible air movement suggests edema may cause post-extubation obstruction. If leak present, proceed but over an AEC (maintains access for re-intubation or O2 delivery if patient fails).' },
  { id: 72, domain: 'III — Pain', q: 'Which mechanism BEST explains how gabapentinoids provide perioperative analgesia?', options: ['Inhibition of COX enzymes reducing prostaglandin synthesis', 'Blockade of voltage-gated calcium channels (alpha-2-delta subunit) in dorsal horn, reducing excitatory neurotransmitter release', 'Competitive antagonism at NMDA glutamate receptors', 'Activation of mu-opioid receptors in spinal cord'], answer: 1, rationale: 'Gabapentinoids (gabapentin, pregabalin) bind to the alpha-2-delta subunit of voltage-gated calcium channels in dorsal horn neurons. This reduces calcium influx at presynaptic terminals → decreased release of excitatory neurotransmitters (glutamate, substance P, CGRP) → reduced central sensitization. Especially effective for neuropathic pain.' },
  { id: 73, domain: 'III — Monitoring', q: 'New 2 mm ST depression leads II and V5, 30 min after femoral-popliteal bypass graft clamping. HR 88, BP 132/82. MOST appropriate immediate response?', options: ['Increase volatile agent to ensure depth of anesthesia', 'Increase HR with atropine to improve coronary perfusion pressure', 'Notify surgeon, obtain 12-lead ECG, check for ischemia signs (TEE wall motion if available), optimize HR and BP to minimize demand ischemia', 'Administer heparin immediately for suspected in-stent thrombosis'], answer: 2, rationale: 'New intraoperative ST depression = likely myocardial ischemia. Immediate: (1) notify surgeon, (2) 12-lead ECG, (3) TEE for wall motion abnormalities, (4) optimize hemodynamics: control HR (avoid tachycardia), maintain adequate diastolic BP, check Hgb, consider nitroglycerin if BP allows. Increasing HR worsens myocardial O2 demand.' },
  { id: 74, domain: 'III — Infection Control', q: 'CRNA draws medications from multidose vials using the same syringe between patients. Which safety concern is MOST directly raised?', options: ['Propofol lipid emulsion instability with repeated injection', 'Transmission of bloodborne pathogens and bacterial contamination — violation of sterile technique; separate syringes per patient are mandatory', 'Excessive opioid waste documentation requirements', 'Increased risk of propofol infusion syndrome from contamination'], answer: 1, rationale: 'Reusing syringes between patients has caused documented outbreaks of hepatitis B, C, and bacterial infections. Propofol lipid emulsion is a bacterial growth medium — particularly susceptible. AANA and CDC mandate: new needle and syringe for every injection, single-use vials preferred, discard unused portions. This is a critical infection control violation.' },
  { id: 75, domain: 'III — PACU', q: 'Neostigmine + glycopyrrolate given; TOF confirmed 0.95 before extubation. Post-extubation: SpO2 drops to 88% with paradoxical chest wall movement. MOST likely diagnosis?', options: ['Residual NMB despite TOF >0.9', 'Opioid-induced respiratory depression', 'Complete laryngospasm', 'Pulmonary embolism'], answer: 2, rationale: 'Laryngospasm presents immediately post-extubation with paradoxical chest wall movement (chest sucks in on inspiration due to airway obstruction), rapidly falling SpO2. Despite TOF >0.9, laryngospasm can still occur — secretions, blood, or stimulation triggers glottic closure independent of NMB. Treatment: jaw thrust, CPAP, 100% O2; succinylcholine 0.5-1 mg/kg if incomplete response.' },
  { id: 76, domain: 'IV — Pediatrics', q: '3-year-old (15 kg) for T&A. During mask induction, complete laryngospasm develops. SpO2 78% and falling. No IV access. MOST appropriate immediate action?', options: ['Discontinue sevoflurane and observe — laryngospasm resolves spontaneously', 'Succinylcholine 60 mg IM (4 mg/kg) in the lateral thigh', 'Atropine 0.3 mg IM to decrease secretions', 'Nasopharyngeal airway insertion immediately'], answer: 1, rationale: 'Complete laryngospasm + SpO2 78% and falling = life-threatening emergency. IM succinylcholine 4 mg/kg (dose compensates for slower IM absorption). For 15 kg: 4 × 15 = 60 mg. Apply 100% O2, jaw thrust, CPAP while awaiting effect (~45-90 sec IM). Simultaneously establish IV access. Complete laryngospasm does NOT resolve spontaneously.' },
  { id: 77, domain: 'IV — Obstetrics', q: 'Parturient 38 weeks, severe preeclampsia (BP 172/108, headache, visual changes). Urgent cesarean. Which anesthetic approach is PREFERRED?', options: ['General anesthesia with RSI — safer for fetus in severe preeclampsia', 'Neuraxial anesthesia (spinal or epidural) if platelet count adequate and no coagulopathy — reduces hypertensive response to intubation', 'General anesthesia required — neuraxial absolutely contraindicated in preeclampsia', 'Ketamine induction for sympathomimetic effects to maintain blood pressure'], answer: 1, rationale: 'Neuraxial anesthesia is PREFERRED in preeclampsia (not contraindicated). Key reasons: (1) avoids severe hypertensive response to laryngoscopy that can cause CVA or pulmonary edema, (2) excellent surgical conditions, (3) avoids fetal drug exposure. GA is reserved for urgent cases with neuraxial contraindications. Ketamine increases BP — dangerous in severe preeclampsia.' },
  { id: 78, domain: 'IV — Cardiac', q: 'After CABG separation from CPB: TEE shows severe RV dilation, septal flattening, TR. BP 70/40. MOST likely complication and treatment?', options: ['LV failure — dobutamine infusion', 'RV failure — milrinone + vasopressin + inhaled nitric oxide', 'Systemic air embolism — hyperbaric oxygen', 'Heparin rebound causing coagulopathy — protamine'], answer: 1, rationale: 'RV failure post-CPB management: (1) optimize preload (not too much — RV dilation worsens TR), (2) reduce RV afterload: inhaled NO or sildenafil, (3) improve contractility: milrinone (PDE3 inhibitor — inotrope + vasodilator), (4) maintain systemic BP: vasopressin (does not increase PVR), (5) consider return to CPB or RVAD.' },
  { id: 79, domain: 'IV — Thoracic', q: 'Right lower lobe lobectomy (OLV): SpO2 falls to 88% despite FiO2 1.0. Which intervention should be attempted FIRST?', options: ['Apply CPAP 5-10 cmH2O to the non-dependent (collapsed) lung', 'Recruit the dependent lung with sustained inflation to 40 cmH2O for 40 seconds', 'Reduce TV to 4 mL/kg to improve V/Q ratio', 'Administer almitrine to augment HPV'], answer: 0, rationale: 'First-line OLV hypoxemia rescue: CPAP 5-10 cmH2O to the non-dependent (collapsed) lung provides O2 to non-ventilated alveoli via diffusion (apneic oxygenation), improving V/Q matching without requiring full lung ventilation. If CPAP fails, next step: intermittent manual PPV to non-dependent lung.' },
  { id: 80, domain: 'IV — Vascular', q: 'CEA under cervical plexus block: patient becomes agitated, develops contralateral arm weakness and dysarthria after carotid cross-clamping. MOST appropriate response?', options: ['Administer midazolam — agitation is common with CEA', 'Immediately inform the surgeon of neurologic changes consistent with carotid ischemia; prepare for shunt placement or conversion to GA', 'Increase BP with phenylephrine to improve collateral flow and observe for 5 minutes', 'Immediately induce GA and place shunt without informing surgeon first'], answer: 1, rationale: 'New neurologic deficits after carotid cross-clamping = cerebral ischemia. The awake patient monitoring advantage is immediately apparent — communicate with surgeon immediately. Surgeon may: (1) place intraluminal shunt to restore flow, (2) increase BP for collateral flow, or (3) expedite closure. Never dismiss new neurologic changes after cross-clamp as "anxiety."' },
  { id: 81, domain: 'IV — Pediatrics', q: '6-week-old former 32-week premature infant (corrected age 42 weeks) for inguinal hernia repair. MOST accurate postoperative management statement?', options: ['Can be safely discharged home same-day after 1-hour PACU stay', 'Requires inpatient monitoring for apnea for at least 12 hours post-op due to prematurity risk', 'Spinal anesthesia is absolutely contraindicated in infants this age', 'Succinylcholine is the preferred induction agent for this patient'], answer: 1, rationale: 'Former premature infants (<37 weeks gestation) are at increased apnea risk up to 60 weeks post-conceptual age (PCA). This infant is 38 weeks PCA — well below threshold. Guidelines recommend ≥12-24 hours inpatient monitoring with cardiorespiratory monitoring. Awake spinal anesthesia is actually PREFERRED to reduce apnea risk.' },
  { id: 82, domain: 'IV — Obstetrics', q: 'Emergency cesarean for placental abruption (category III FHR). Epidural in place with 0.0625% bupivacaine + fentanyl. FASTEST way to achieve surgical anesthesia?', options: ['Remove epidural and perform spinal', 'Rapid epidural bolus loading: 3% 2-chloroprocaine 15-20 mL (or 2% lidocaine + epi + bicarb)', 'Induce general anesthesia with RSI immediately', 'Continue labor epidural infusion — onset within 5 minutes'], answer: 1, rationale: 'Emergency cesarean with functioning epidural: epidural top-up is fastest approach. Fastest agent: 3% 2-chloroprocaine (onset 5-8 min to surgical level). Alternative: 2% lidocaine + sodium bicarbonate ± epinephrine (onset ~10 min). Key principle: a functioning epidural catheter can be loaded rapidly for urgent cesarean. A dilute labor infusion will NEVER provide surgical anesthesia without bolus loading.' },
  { id: 83, domain: 'IV — Geriatrics', q: '85-year-old with moderate dementia, multiple myeloma, hip fracture repair. Which pharmacokinetic change is MOST clinically relevant to anesthetic dosing?', options: ['Increased hepatic enzyme induction requiring higher drug doses', 'Increased Vd, decreased albumin, decreased renal and hepatic clearance — requiring dose reduction and longer intervals', 'Decreased fat stores requiring lower lipid-soluble drug doses only', 'Increased renal clearance due to compensation for hepatic decline'], answer: 1, rationale: 'Elderly pharmacokinetic changes: (1) increased body fat → larger Vd for lipophilic drugs, (2) decreased albumin → more free drug, (3) decreased hepatic mass/blood flow → reduced Phase I metabolism, (4) decreased GFR (~1%/year after age 40). Clinical consequence: use lower doses and longer intervals for all anesthetic agents.' },
  { id: 84, domain: 'IV — Obesity', q: 'Morbidly obese patient (TBW 140 kg, IBW 75 kg) requires succinylcholine for RSI. Which correctly describes the dose?', options: ['Based on IBW (75 kg): succinylcholine 112 mg (1.5 mg/kg IBW)', 'Based on TBW (140 kg): succinylcholine 210 mg (1.5 mg/kg TBW)', 'Based on lean body weight (~100 kg): succinylcholine 150 mg', 'Use fixed dose of 200 mg regardless of weight'], answer: 1, rationale: 'Succinylcholine in obese patients uses TBW — pseudocholinesterase activity is increased in proportion to TBW. Using IBW provides inadequate intubating conditions. For 140 kg at 1.5 mg/kg TBW: 210 mg. Contrast: NDNMBs (rocuronium, vecuronium) are dosed based on IBW or LBW to prevent prolonged paralysis.' },
  { id: 85, domain: 'IV — Neurosurgery', q: 'Endovascular coiling of ruptured cerebral aneurysm: BP suddenly increases from 110/70 to 180/120 and patient\'s head moves. MOST immediately life-threatening complication?', options: ['Pressure-induced retinal hemorrhage', 'Aneurysm re-rupture during coiling from movement and hypertension', 'Contrast nephropathy from angiographic dye', 'Vasospasm from hypertension'], answer: 1, rationale: 'Aneurysm re-rupture carries ~80% mortality. Both hypertension (increased transmural pressure) and patient movement can precipitate re-rupture before the aneurysm is secured. Tight BP control and adequate NMB depth throughout the procedure are critical. Controlled hypotension (MAP 60-70% baseline) often targeted during coil deployment.' },
  { id: 86, domain: 'IV — Pediatrics', q: '2-year-old with Pierre Robin sequence and prior difficult intubation requires GA for myringotomy. MOST appropriate airway strategy?', options: ['Standard inhalation induction with Macintosh blade', 'Maintain spontaneous ventilation with sevoflurane inhalation; have video laryngoscope, fiberoptic scope, and LMA available; intubate only if necessary', 'Proceed with RSI — succinylcholine will relax tongue and facilitate laryngoscopy', 'Insert LMA first, then exchange for ETT blindly over tube exchanger'], answer: 1, rationale: 'Pierre Robin sequence (micrognathia, glossoptosis, cleft palate) + prior difficult intubation = anticipated difficult airway. Maintain spontaneous ventilation with sevoflurane. Have all advanced airway tools immediately available. RSI is contraindicated when difficult airway is anticipated — commits to apnea with known difficult airway.' },
  { id: 87, domain: 'IV — Orthopedics', q: 'During cementation of femoral component in THA: BP drops from 120/80 to 72/44, SpO2 88%, HR 118. MOST likely complication?', options: ['Transfusion reaction from PRBCs 20 min ago', 'Bone cement implantation syndrome (BCIS) — venous embolism of fat, marrow, and cement monomer', 'Anaphylaxis to latex from surgical gloves', 'Air embolism from femoral canal'], answer: 1, rationale: 'BCIS occurs during/immediately after cementation due to: (1) embolization of fat, bone marrow, air, cement monomer into pulmonary circulation during medullary canal pressurization, (2) vasoactive mediator release. Presentation: sudden cardiovascular collapse timed to cementation. High-risk: elderly, poor cardiopulmonary reserve, pathologic fractures.' },
  { id: 88, domain: 'IV — Non-OR Anesthesia', q: 'CRNA provides ECT anesthesia for patient on phenelzine (MAOI). SAFEST anesthetic combination?', options: ['Meperidine + propofol — meperidine has less MAOI interaction', 'Methohexital (or propofol) + succinylcholine; avoid all indirect sympathomimetics; have phentolamine for hypertensive crisis', 'Ketamine + midazolam — standard ECT combination', 'Fentanyl + sevoflurane — provides deep enough anesthesia'], answer: 1, rationale: 'MAOIs + meperidine = ABSOLUTE contraindication (fatal serotonin syndrome or hyperpyrexic reaction). MAOIs + indirect sympathomimetics (ephedrine, dopamine) = hypertensive crisis. Safe ECT with MAOI: methohexital or propofol (lower seizure threshold) + succinylcholine. Have phentolamine available for expected hypertensive surge. Ketamine dangerous with MAOIs.' },
  { id: 89, domain: 'IV — Obstetrics', q: 'Complete placenta previa, 1500 mL blood loss, hemodynamically unstable (BP 84/52, HR 128), urgent cesarean. MOST appropriate anesthetic approach?', options: ['Spinal anesthesia — fastest and avoids fetal drug exposure', 'General anesthesia with RSI — hemodynamic instability and urgency contraindicate spinal', 'Epidural anesthesia — slower onset allows hemodynamic stabilization', 'Local infiltration with IV ketamine sedation'], answer: 1, rationale: 'Active hemorrhage with hemodynamic instability is a relative-to-absolute contraindication to spinal. Spinal causes sympathectomy → vasodilation → cardiovascular collapse in a hemorrhaging patient who is already vasoconstrictive and compensating. GA with RSI: ketamine or etomidate + succinylcholine/rocuronium, left uterine displacement, prepare for MTP, notify IR team (accreta risk).' },
  { id: 90, domain: 'IV — Trauma', q: 'Trauma patient: absent breath sounds right, tracheal deviation left, distended neck veins, BP 72/40, HR 148, SpO2 not obtainable. MOST appropriate IMMEDIATE intervention?', options: ['Chest X-ray to confirm before treatment', 'CT scan of the chest to localize the pneumothorax', 'Needle decompression at 2nd intercostal space, midclavicular line, right side', 'Immediate intubation and positive pressure ventilation'], answer: 2, rationale: 'Tension pneumothorax is a CLINICAL diagnosis — do NOT delay for imaging. Immediate needle decompression: 14-16g IV catheter at 2nd ICS, MCL on affected side (right). Converts tension to simple pneumothorax. Follow with tube thoracostomy. PPV in tension PTX increases intrathoracic pressure — worsening venous return collapse. Never delay treatment for imaging.' },
  { id: 91, domain: 'IV — Cardiac', q: 'After aortic valve replacement: patient hypotensive despite volume loading. TEE shows hyperdynamic LV, small end-diastolic volume, systolic anterior motion (SAM) of mitral valve. MOST appropriate treatment?', options: ['Dobutamine infusion to increase contractility', 'Phenylephrine bolus, volume loading, discontinuation of inotropes, possible beta-blockade', 'Vasodilator (nitroglycerin) to reduce preload', 'Intraaortic balloon pump placement'], answer: 1, rationale: 'SAM of mitral valve post-AVR = dynamic LVOTO (HOCM-like physiology). Treatment mirrors HOCM: (1) increase preload (volume), (2) increase afterload (phenylephrine — NOT vasodilators!), (3) reduce contractility (stop inotropes, consider beta-blockade), (4) slow HR. Dobutamine and vasodilators WORSEN SAM and LVOTO.' },
  { id: 92, domain: 'IV — Special Populations', q: 'Sickle cell disease (HbSS) patient for laparoscopic cholecystectomy. MOST important perioperative consideration?', options: ['Transfuse to hematocrit >40% to prevent perioperative sickling', 'Maintain adequate oxygenation, hydration, normothermia, avoid acidosis/hypoxia; consider preoperative exchange transfusion targeting HbS <30%', 'Administer hydroxyurea 500 mg preoperatively', 'Use N2O as primary anesthetic to avoid hemoglobin binding by volatile agents'], answer: 1, rationale: 'Sickle cell management: prevent sickling triggers — hypoxia, acidosis, hypothermia, dehydration, pain. Exchange transfusion (targeting HbS fraction <30%) recommended before major surgery. Simple transfusion to Hct >40% is NOT recommended — increases blood viscosity dangerously. Warm IV fluids, active warming, adequate analgesia, hydration throughout.' },
  { id: 93, domain: 'IV — Neurosurgery', q: 'Awake craniotomy for glioblastoma near Broca\'s area. Patient suddenly develops generalized tonic-clonic seizure. MOST appropriate immediate intervention?', options: ['Administer propofol 100 mg IV to terminate seizure', 'Irrigate cortical surface with cold (iced) saline', 'Administer midazolam 2-4 mg IV; if seizure persists, add propofol in small increments; ensure airway protection', 'Perform awake fiberoptic intubation immediately'], answer: 2, rationale: 'Intraoperative seizure during awake craniotomy: midazolam 2-4 mg IV is first-line (anticonvulsant with minimal respiratory depression). If refractory, propofol in small increments terminates seizures but may cause significant sedation, ending the awake phase. Airway protection takes priority if consciousness is impaired. Notify surgeon and neurophysiologist.' },
  { id: 94, domain: 'IV — NORA', q: 'Deep sedation for RFA in IR suite: BMI 38, STOP-BANG 5. 30 min in: SpO2 88%, ETCO2 65, minimally arousable. MOST appropriate initial intervention?', options: ['Increase supplemental oxygen to 15 L/min by face mask', 'Stop sedation infusion, apply jaw thrust, attempt CPAP by mask, prepare for emergent intubation if not improving', 'Administer flumazenil to reverse sedation', 'Apply nasal CPAP device and increase FiO2'], answer: 1, rationale: 'Over-sedation with airway obstruction (rising ETCO2) and hypoxemia in a high STOP-BANG patient. Immediate: (1) stop/reduce sedation infusion, (2) jaw thrust/airway maneuvers, (3) CPAP by mask with 100% O2, (4) prepare for intubation if not improving rapidly. Increasing O2 alone does not treat the obstruction. Flumazenil only reverses benzodiazepines.' },
  { id: 95, domain: 'IV — Obstetrics', q: 'Epidural at L3-L4 for labor analgesia. After test dose (3 mL of 1.5% lidocaine with 1:200,000 epi), HR increases from 78 to 102 bpm with palpitations within 60 seconds. What does this indicate?', options: ['Normal sympathetic response to epidural analgesia', 'Positive intravascular test dose — catheter likely in epidural vein; do not inject further; reposition catheter', 'Subarachnoid placement — patient developing high spinal', 'Systemic lidocaine toxicity from the test dose'], answer: 1, rationale: 'Epidural test dose contains epinephrine 1:200,000 (15 mcg per 3 mL). Intravascular injection → HR increase >20 bpm within 60-90 seconds = POSITIVE intravascular test dose. The catheter is in an epidural vein. Do NOT inject further. Remove and replace catheter at different level. This prevents catastrophic LAST from injecting large epidural dose IV.' },
  { id: 96, domain: 'IV — Vascular', q: 'EVAR: patient develops sudden bilateral lower extremity flaccid paralysis immediately after stent graft deployment. Complication and treatment?', options: ['Anaphylaxis to contrast dye — treat with epinephrine', 'Spinal cord ischemia from coverage of critical segmental arteries (Adamkiewicz); treat with CSF drainage and BP augmentation', 'Peripheral arterial embolism; treat with heparin bolus', 'Propofol infusion syndrome; treat by stopping propofol'], answer: 1, rationale: 'Spinal cord ischemia after EVAR occurs when the stent graft covers critical segmental arteries supplying the anterior spinal artery (artery of Adamkiewicz, T9-L1). Immediate treatment: (1) lumbar CSF drainage (target CSF pressure <10 mmHg → improves spinal cord perfusion pressure), (2) vasopressors to augment MAP to 85-100 mmHg, (3) optimize Hgb.' },
  { id: 97, domain: 'IV — Pediatrics', q: '5-year-old (20 kg) with stridor, drooling, high fever, tripod position. Suspected epiglottitis. Which approach is MOST appropriate?', options: ['RSI with succinylcholine on the ER stretcher', 'Take to OR immediately; inhalation induction maintaining spontaneous ventilation; have ENT scrubbed for emergency tracheotomy; have all ETT sizes available', 'Attempt awake nasal intubation with 4.0 ETT', 'Immediate cricothyrotomy — epiglottitis always requires surgical airway'], answer: 1, rationale: 'Epiglottitis: (1) Transfer to OR immediately — do NOT agitate the child, (2) Inhalation induction with sevoflurane maintaining spontaneous ventilation, (3) Achieve adequate depth before laryngoscopy, (4) ENT surgeon scrubbed and ready for emergency tracheotomy, (5) All ETT sizes available (swollen epiglottis may require smaller tube), (6) IV access after induction. RSI risks apnea in potentially unclearable airway.' },
  { id: 98, domain: 'IV — Substance Use', q: 'Patient on methadone 80 mg/day for OUD requires major abdominal surgery. MOST appropriate perioperative pain management?', options: ['Hold methadone morning of surgery to reduce opioid load', 'Continue methadone through surgery; add regional technique and multimodal analgesia; titrate full-agonist opioids to effect if needed', 'Switch to buprenorphine-naloxone on admission', 'Administer naltrexone to clear methadone before surgery'], answer: 1, rationale: 'ASAM/AANA guidance: continue methadone perioperatively. Abrupt discontinuation precipitates withdrawal and removes tolerance maintenance. Methadone\'s NMDA antagonist properties may assist perioperative pain. Plan: (1) continue methadone, (2) regional anesthesia, (3) multimodal analgesia, (4) full-agonist IV opioids in higher-than-usual doses for breakthrough. Naltrexone precipitates immediate withdrawal — absolutely contraindicated.' },
  { id: 99, domain: 'IV — Special Populations', q: 'Severe AS (AVA 0.7 cm², gradient 68 mmHg) requires emergency bowel resection. Which induction agent BEST preserves hemodynamic profile needed in AS?', options: ['Propofol 2 mg/kg — rapid and predictable', 'Etomidate 0.3 mg/kg — hemodynamically stable, minimal vasodilation', 'Ketamine 2 mg/kg — sympathomimetic effect will prevent hypotension', 'Thiopental 4 mg/kg — potent induction with brief duration'], answer: 1, rationale: 'Severe AS hemodynamic goals: maintain sinus rhythm HR 60-80, maintain SVR (avoid vasodilation), maintain preload. Etomidate provides rapid induction with minimal cardiovascular depression and minimal vasodilation — the induction agent of choice for hemodynamically unstable cardiac patients. Propofol and thiopental cause significant vasodilation → catastrophic hypotension in AS. Ketamine increases HR — worsens subendocardial ischemia.' },
  { id: 100, domain: 'IV — Special Populations', q: 'Liver failure patient (INR 3.2, bilirubin 12, encephalopathy grade II) requires urgent laparotomy. Which NMB agent is MOST appropriate?', options: ['Vecuronium — primarily renal elimination in liver failure', 'Rocuronium — rapid onset with sugammadex reversal available', 'Cisatracurium — Hofmann elimination ensures predictable duration independent of liver function', 'Pancuronium — vagolytic effect is beneficial in shock'], answer: 2, rationale: 'Cisatracurium undergoes Hofmann elimination — spontaneous, pH- and temperature-dependent chemical degradation in plasma, completely organ-independent. Ideal in both liver and renal failure. Vecuronium and rocuronium are primarily hepatically eliminated → dramatically prolonged in liver failure (even with sugammadex available). Cisatracurium is the NDNMB of choice in organ failure.' },
];

const DOMAIN_COLORS = {
  'I': { bg: 'bg-blue-50', border: 'border-blue-200', badge: 'bg-blue-100 text-blue-700' },
  'II': { bg: 'bg-purple-50', border: 'border-purple-200', badge: 'bg-purple-100 text-purple-700' },
  'III': { bg: 'bg-green-50', border: 'border-green-200', badge: 'bg-green-100 text-green-700' },
  'IV': { bg: 'bg-orange-50', border: 'border-orange-200', badge: 'bg-orange-100 text-orange-700' },
};

function getDomainNum(domain) {
  if (domain.startsWith('I —')) return 'I';
  if (domain.startsWith('II —')) return 'II';
  if (domain.startsWith('III —')) return 'III';
  return 'IV';
}

function ScoreBar({ score, total }) {
  const pct = total > 0 ? Math.round((score / total) * 100) : 0;
  const color = pct >= 85 ? 'bg-emerald-500' : pct >= 75 ? 'bg-teal-500' : pct >= 65 ? 'bg-amber-500' : 'bg-red-500';
  const label = pct >= 85 ? 'Exceptional preparation!' : pct >= 75 ? 'Well-prepared!' : pct >= 65 ? 'Targeted review recommended' : 'Intensive review needed';
  return (
    <div>
      <div className="flex items-center justify-between mb-1">
        <span className="text-sm font-semibold text-foreground">{score}/{total} correct ({pct}%)</span>
        <span className="text-xs text-muted-foreground">{label}</span>
      </div>
      <div className="w-full h-2.5 bg-secondary rounded-full overflow-hidden">
        <div className={`h-full rounded-full transition-all duration-700 ${color}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

export default function NCEPracticeTest() {
  const { isEntitled } = useEntitlement();
  const [paywallOpen, setPaywallOpen] = useState(false);
  const [showGate, setShowGate] = useState(false);
  const [currentQ, setCurrentQ] = useState(0);
  const [selected, setSelected] = useState(null);
  const [showAnswer, setShowAnswer] = useState(false);
  const [answers, setAnswers] = useState({});
  const [mode, setMode] = useState('test'); // 'test' | 'results' | 'review'
  const [reviewQ, setReviewQ] = useState(0);
  const [showRationale, setShowRationale] = useState(false);

  const availableQuestions = isEntitled ? QUESTIONS : QUESTIONS.slice(0, FREE_PREVIEW_LIMIT);

  // Scroll to top whenever the question or mode changes so the question is visible
  useScrollReset([currentQ, reviewQ, mode]);

  const q = availableQuestions[currentQ];
  const domNum = getDomainNum(q.domain);
  const colors = DOMAIN_COLORS[domNum];
  const answered = answers[q.id] !== undefined;
  const totalAnswered = Object.keys(answers).length;
  const totalCorrect = Object.values(answers).filter(a => a.correct).length;

  function handleSelect(idx) {
    if (showAnswer) return;
    setSelected(idx);
    setShowAnswer(true);
    setAnswers(prev => ({ ...prev, [q.id]: { chosen: idx, correct: idx === q.answer } }));
  }

  function handleNext() {
    setSelected(null);
    setShowAnswer(false);
    if (currentQ < availableQuestions.length - 1) {
      setCurrentQ(currentQ + 1);
    } else if (isEntitled) {
      setMode('results');
    } else {
      setShowGate(true);
    }
  }

  function handleReset() {
    setCurrentQ(0);
    setSelected(null);
    setShowAnswer(false);
    setAnswers({});
    setMode('test');
    setReviewQ(0);
    setShowGate(false);
  }

  function getOptionStyle(idx) {
    if (!showAnswer) {
      return selected === idx ? 'bg-primary/10 border-primary ring-1 ring-primary' : 'bg-card border-border hover:bg-secondary/50';
    }
    if (idx === q.answer) return 'bg-emerald-50 border-emerald-300 ring-1 ring-emerald-400';
    if (idx === selected && idx !== q.answer) return 'bg-red-50 border-red-300 ring-1 ring-red-400';
    return 'bg-background border-border opacity-50';
  }

  // RESULTS MODE
  if (mode === 'results') {
    const pct = Math.round((totalCorrect / QUESTIONS.length) * 100);
    const domainStats = { I: { correct: 0, total: 0 }, II: { correct: 0, total: 0 }, III: { correct: 0, total: 0 }, IV: { correct: 0, total: 0 } };
    QUESTIONS.forEach(qn => {
      const d = getDomainNum(qn.domain);
      domainStats[d].total++;
      if (answers[qn.id]?.correct) domainStats[d].correct++;
    });
    return (
      <div className="flex flex-col gap-4">
        <div className="bg-teal-700 text-white rounded-2xl p-5 text-center">
          <Trophy className="w-10 h-10 mx-auto mb-2 opacity-90" />
          <h2 className="font-bold text-xl">Test Complete!</h2>
          <p className="text-4xl font-bold mt-1">{pct}%</p>
          <p className="text-sm opacity-80 mt-1">{totalCorrect} / {QUESTIONS.length} correct</p>
        </div>

        <div className="bg-background rounded-2xl border border-border p-4 space-y-3">
          <h3 className="font-bold text-sm text-foreground">Results by Domain</h3>
          {Object.entries(domainStats).map(([d, stat]) => {
            const dpct = Math.round((stat.correct / stat.total) * 100);
            const colors2 = DOMAIN_COLORS[d];
            return (
              <div key={d} className={`rounded-xl p-3 border ${colors2.bg} ${colors2.border}`}>
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs font-semibold text-foreground">Domain {d}</span>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors2.badge}`}>{stat.correct}/{stat.total} ({dpct}%)</span>
                </div>
                <div className="w-full h-1.5 bg-card/50 rounded-full overflow-hidden">
                  <div className="h-full bg-current rounded-full transition-all duration-500" style={{ width: `${dpct}%` }} />
                </div>
              </div>
            );
          })}
        </div>

        <div className="bg-amber-50 border border-amber-200 rounded-xl p-3">
          <p className="text-xs text-amber-800 font-medium">Performance targets: Below 65% = intensive review | 65-74% = targeted review | 75%+ = well-prepared | 85%+ = exceptional preparation</p>
        </div>

        <div className="flex gap-2">
          <button onClick={() => { setMode('review'); setReviewQ(0); setShowRationale(false); }}
            className="flex-1 py-3 bg-teal-50 border border-teal-200 rounded-xl text-sm font-semibold text-teal-700 active:scale-95 transition-all">
            📖 Review Answers
          </button>
          <button onClick={handleReset}
            className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-semibold active:scale-95 transition-all flex items-center justify-center gap-1">
            <RotateCcw className="w-4 h-4" /> Restart Test
          </button>
        </div>
        <p className="text-xs text-muted-foreground text-center">© CE HALO LLC — For educational use only. Not for clinical decision-making.</p>
      </div>
    );
  }

  // REVIEW MODE
  if (mode === 'review') {
    const rq = QUESTIONS[reviewQ];
    const rDomNum = getDomainNum(rq.domain);
    const rColors = DOMAIN_COLORS[rDomNum];
    const userAnswer = answers[rq.id];
    return (
      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <button onClick={() => setMode('results')} className="flex items-center gap-1 text-primary text-sm font-medium">
            <ChevronLeft className="w-4 h-4" /> Results
          </button>
          <span className="text-xs text-muted-foreground">Q{reviewQ + 1} of {QUESTIONS.length}</span>
        </div>

        <div className={`rounded-xl p-3 border ${rColors.bg} ${rColors.border}`}>
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${rColors.badge}`}>Domain {rDomNum} — {rq.domain.split(' — ')[1]}</span>
          <p className="text-sm font-semibold text-foreground mt-2 leading-relaxed">{rq.q}</p>
        </div>

        <div className="flex flex-col gap-2">
          {rq.options.map((opt, idx) => {
            let style = 'bg-background border-border';
            let icon = null;
            if (idx === rq.answer) { style = 'bg-emerald-50 border-emerald-300'; icon = <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />; }
            else if (userAnswer?.chosen === idx && idx !== rq.answer) { style = 'bg-red-50 border-red-300'; icon = <XCircle className="w-4 h-4 text-red-500 shrink-0" />; }
            return (
              <div key={idx} className={`flex items-start gap-2 p-3 rounded-xl border ${style}`}>
                <span className="text-xs font-bold text-muted-foreground shrink-0 mt-0.5">{String.fromCharCode(65 + idx)}.</span>
                <p className="text-xs text-foreground flex-1">{opt}</p>
                {icon}
              </div>
            );
          })}
        </div>

        <button onClick={() => setShowRationale(r => !r)}
          className="flex items-center justify-between w-full p-3 bg-teal-50 border border-teal-200 rounded-xl text-sm font-semibold text-teal-700 active:scale-95 transition-all">
          <span>📖 Rationale</span>
          {showRationale ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
        </button>
        {showRationale && (
          <div className="p-3 bg-teal-50/50 border border-teal-200 rounded-xl">
            <p className="text-xs text-foreground leading-relaxed">{rq.rationale}</p>
          </div>
        )}

        <div className="flex gap-2">
          <button onClick={() => { setReviewQ(r => Math.max(0, r - 1)); setShowRationale(false); }}
            disabled={reviewQ === 0}
            className="flex-1 py-3 bg-secondary border border-border rounded-xl text-sm font-semibold text-muted-foreground disabled:opacity-40 active:scale-95 transition-all flex items-center justify-center gap-1">
            <ChevronLeft className="w-4 h-4" /> Prev
          </button>
          <button onClick={() => { setReviewQ(r => Math.min(QUESTIONS.length - 1, r + 1)); setShowRationale(false); }}
            disabled={reviewQ === QUESTIONS.length - 1}
            className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-semibold disabled:opacity-40 active:scale-95 transition-all flex items-center justify-center gap-1">
            Next <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    );
  }

  // FREE PREVIEW GATE
  if (showGate) {
    return (
      <>
        <QuizFreePreviewGate
          answeredCount={FREE_PREVIEW_LIMIT}
          totalQuestions={QUESTIONS.length}
          onSubscribe={() => setPaywallOpen(true)}
          onBack={handleReset}
        />
        <PaywallModal open={paywallOpen} onClose={() => setPaywallOpen(false)} />
      </>
    );
  }

  // TEST MODE
  return (
    <div className="flex flex-col gap-3">
      {/* Header */}
      <div className="bg-teal-700 text-white px-4 py-4 rounded-2xl">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <BookOpen className="w-5 h-5" />
            <span className="text-xs font-bold uppercase tracking-widest opacity-80">CE HALO LLC</span>
          </div>
          <button onClick={handleReset}
            className="flex items-center gap-1 px-2.5 py-1.5 bg-card/20 hover:bg-card/30 rounded-lg text-xs font-semibold transition-all active:scale-95">
            <RotateCcw className="w-3.5 h-3.5" /> Reset
          </button>
        </div>
        <h2 className="font-bold text-base">NBCRNA NCE Practice Test</h2>
        <p className="text-xs opacity-70">100 Board-Style Questions · All Four Domains</p>
      </div>

      {/* Progress */}
      <div             className="bg-background rounded-2xl border border-border p-3">
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-semibold text-foreground">Question {currentQ + 1} of {availableQuestions.length}</span>
          <span className="text-xs text-muted-foreground">{totalAnswered} answered · {totalCorrect} correct</span>
        </div>
        <ScoreBar score={totalCorrect} total={totalAnswered} />
      </div>

      {/* Domain badge */}
      <div className={`rounded-xl p-3 border ${colors.bg} ${colors.border}`}>
        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors.badge}`}>Domain {domNum} — {q.domain.split(' — ')[1]}</span>
        <p className="text-sm font-semibold text-foreground mt-2 leading-relaxed">{q.q}</p>
      </div>

      {/* Options */}
      <div className="flex flex-col gap-2">
        {q.options.map((opt, idx) => (
          <button key={idx} onClick={() => handleSelect(idx)}
            className={`flex items-start gap-2 p-3 rounded-xl border text-left transition-all active:scale-[0.98] ${getOptionStyle(idx)}`}>
            <span className="text-xs font-bold text-muted-foreground shrink-0 mt-0.5 min-w-[16px]">{String.fromCharCode(65 + idx)}.</span>
            <p className="text-xs text-foreground leading-relaxed">{opt}</p>
            {showAnswer && idx === q.answer && <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0 ml-auto" />}
            {showAnswer && idx === selected && idx !== q.answer && <XCircle className="w-4 h-4 text-red-500 shrink-0 ml-auto" />}
          </button>
        ))}
      </div>

      {/* Rationale */}
      {showAnswer && (
        <div className="p-3 bg-teal-50 border border-teal-200 rounded-xl">
          <p className="text-xs font-semibold text-teal-700 mb-1">
            {selected === q.answer ? '✅ Correct!' : '❌ Incorrect'} — Rationale
          </p>
          <p className="text-xs text-foreground leading-relaxed">{q.rationale}</p>
        </div>
      )}

      {/* Navigation */}
      <div className="flex gap-2">
        <button onClick={() => {
          const prevIdx = Math.max(0, currentQ - 1);
          const prevQ = availableQuestions[prevIdx];
          const prevAnswer = answers[prevQ.id];
          setCurrentQ(prevIdx);
          setSelected(prevAnswer?.chosen ?? null);
          setShowAnswer(prevAnswer !== undefined);
        }}
          disabled={currentQ === 0}
          className="px-4 py-3 bg-secondary border border-border rounded-xl text-sm font-semibold text-muted-foreground disabled:opacity-40 active:scale-95 transition-all">
          <ChevronLeft className="w-4 h-4" />
        </button>
        <button onClick={handleNext}
          disabled={!showAnswer}
          className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-semibold disabled:opacity-40 active:scale-95 transition-all flex items-center justify-center gap-1">
          {currentQ === QUESTIONS.length - 1 ? 'View Results' : 'Next Question'} <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      <p className="text-xs text-muted-foreground text-center">© CE HALO LLC — For educational use only. Not for clinical decision-making.</p>
    </div>
  );
}